  rejects(()->PhotoMath.depth(50,8,.05,.03));rejects(()->PhotoMath.nd(86400,30));rejects(()->PhotoMath.flash(36,100,0,9));rejects(()->PhotoMath.shutter(Double.NaN,100,8,0));
  near(PhotoMath.meterIsoStep(400,1),500,0);near(PhotoMath.meterIsoStep(400,-1),320,0);near(PhotoMath.meterIsoStep(25,-1),25,0);near(PhotoMath.meterIsoStep(6400,1),6400,0);rejects(()->PhotoMath.meterIsoStep(111,1));rejects(()->PhotoMath.meterIsoStep(400,0));near(PhotoMath.shutter(12,500,8,0)/PhotoMath.shutter(12,400,8,0),.8,1e-12);
