  if(PhotoMath.METER_ISOS.length!=25||PhotoMath.nearestMeterIso(0)!=400||PhotoMath.nearestMeterIso(-1)!=400||PhotoMath.nearestMeterIso(1)!=25||PhotoMath.nearestMeterIso(102400)!=6400||PhotoMath.nearestMeterIso(112)!=125||PhotoMath.nearestMeterIso(111)!=100||PhotoMath.nearestMeterIso(400)!=400||PhotoMath.nearestMeterIso(450)!=500)throw new AssertionError("ISO scale logarithmic nearest/default/clamps");
  if(!PhotoMath.meterMemo("Current note • ISO 100",200).equals("Current note • ISO 200")||!PhotoMath.meterMemo("ISO 100 in prose",400).equals("ISO 100 in prose • ISO 400")||!PhotoMath.meterMemo("",125).equals("ISO 125"))throw new AssertionError("meter ISO memo preserves prose and replaces exact token");rejects(()->PhotoMath.meterMemo("Current note",111));
  if(PhotoMath.effectiveIso(50,-2)!=13||PhotoMath.effectiveIso(125,-2)!=31||PhotoMath.effectiveIso(1,-2)!=0||PhotoMath.effectiveIso(2,-2)!=1||PhotoMath.effectiveIso(102400,3)!=819200)throw new AssertionError("original EI rounding and bounds");
  for(int iso=0;iso<=102400;iso++)for(int stops=-2;stops<=3;stops++){long numerator=iso*(stops<0?1:1L<<stops),denominator=stops<0?1L<<-stops:1;long quotient=numerator/denominator,remainder=numerator%denominator;if(remainder*2>=denominator)quotient++;if(PhotoMath.effectiveIso(iso,stops)!=quotient)throw new AssertionError("EI rational oracle");}
  if(!PhotoMath.isoEiLabel(100,0).equals("ISO 100")||!PhotoMath.isoEiLabel(50,-2).equals("ISO 50 · EI 13")||!PhotoMath.isoEiLabel(100,2).equals("ISO 100 · EI 400"))throw new AssertionError("original ISO/EI conditional header");
  rejects(()->PhotoMath.effectiveIso(-1,0));rejects(()->PhotoMath.effectiveIso(102401,0));rejects(()->PhotoMath.effectiveIso(100,-3));rejects(()->PhotoMath.effectiveIso(100,4));
  System.out.println("PASS: original 25-step meter ISO/log nearest/default400; exact original ISO/EI rounding and six-stop bounds; ND, manufacturer reciprocity example and one-second boundary, EV/ISO/compensation, thin-lens depth and hyperfocal infinity, flash GN/ISO/power, invalid values and overflow");
